UPDATE "page" SET "schema" = (SELECT coalesce(jsonb_agg(d - 'inherit' ORDER BY i), '[]'::jsonb) FROM jsonb_array_elements("schema") WITH ORDINALITY AS e(d, i)) WHERE jsonb_typeof("schema") = 'array' AND jsonb_path_exists("schema", '$[*].inherit');--> statement-breakpoint
UPDATE "trait" SET "properties" = (SELECT coalesce(jsonb_agg(d - 'inherit' ORDER BY i), '[]'::jsonb) FROM jsonb_array_elements("properties") WITH ORDINALITY AS e(d, i)) WHERE jsonb_typeof("properties") = 'array' AND jsonb_path_exists("properties", '$[*].inherit');--> statement-breakpoint
UPDATE "page_version" SET "schema" = (SELECT coalesce(jsonb_agg(d - 'inherit' ORDER BY i), '[]'::jsonb) FROM jsonb_array_elements("schema") WITH ORDINALITY AS e(d, i)) WHERE jsonb_typeof("schema") = 'array' AND jsonb_path_exists("schema", '$[*].inherit');--> statement-breakpoint
UPDATE "extension" SET "manifest" = jsonb_set("manifest", '{propertyTypes}', (SELECT coalesce(jsonb_agg(t - 'inheritByDefault' ORDER BY i), '[]'::jsonb) FROM jsonb_array_elements("manifest"->'propertyTypes') WITH ORDINALITY AS e(t, i))) WHERE jsonb_typeof("manifest"->'propertyTypes') = 'array' AND jsonb_path_exists("manifest", '$.propertyTypes[*].inheritByDefault');
